import { cmsText, CmsTag } from "@/lib/cms";

// Generated by the CMS from its pages (skipping "noindex" ones) and news articles, or the custom sitemap
// uploaded under SEO › Sitemap & Robots. Refreshed whenever settings, a page's SEO or an article change.
const PAGE_SLUGS = ["home", "about", "leadership", "initiatives", "events", "news-and-articles", "contact", "membership"];

export async function GET() {
  const body = await cmsText("/sitemap.xml", [CmsTag.site, CmsTag.news, ...PAGE_SLUGS.map(CmsTag.page)]);
  if (body === null) return new Response("Not found", { status: 404 }); // sitemap switched off in the CMS
  return new Response(body, { headers: { "Content-Type": "application/xml; charset=utf-8" } });
}
